WITH base AS (SELECT *, amount/quantity AS unit_price_recomputed, year(document_date_parsed) AS year, month(document_date_parsed) AS transaction_month, AVG(amount) OVER(PARTITION BY date_format(document_date_parsed,'yyyy-MM'),buyer_name,product_category) peer_average_amount FROM dedup_ranked WHERE duplicate_rank=1), identified AS (SELECT *, coalesce(unit_price,unit_price_recomputed) AS normalized_unit_price, concat('T',lpad(substr(regexp_replace(reference_no,'\\D',''),-3),3,'0'),substr(lpad(CAST(CAST(round(peer_average_amount) AS BIGINT) AS STRING),2,'0'),1,2),date_format(document_date_parsed,'MM'),substr(buyer_name,1,1)) AS trade_identifier FROM base) SELECT *, sha2(trade_identifier,256) AS hashed_trade_identifier FROM identified
